                </MediaUploadCheck>
            </InspectorControls>
            <h2>{ heading }</h2>
            <RichText
                tagName="p"
                value={ paragraph }
                onChange={ ( newParagraph ) => setAttributes( { paragraph: newParagraph } ) }
            />
            { image && (
                <img src={ image.url } alt={ image.alt } />
            ) }
        </div>
    );
}

function Save( { attributes } ) {
    const { heading, paragraph, image } = attributes;

